// Read-only visual/formula QA of a synthetic workbook generated by the app.
import fs from 'node:fs/promises'
import path from 'node:path'
import { createRequire } from 'node:module'
import { pathToFileURL } from 'node:url'
import assert from 'node:assert/strict'
const [out,runtime]=process.argv.slice(2)
const load=createRequire(path.join(runtime,'runtime-loader.cjs'))
const {FileBlob,SpreadsheetFile}=await import(pathToFileURL(load.resolve('@oai/artifact-tool')).href)
const workbook=await SpreadsheetFile.importXlsx(await FileBlob.load(path.join(out,'dromic-sample.xlsx')))
workbook.recalculate()
console.log((await workbook.inspect({kind:'table',range:'Relief!A7:F10',include:'values,formulas',tableMaxRows:4,tableMaxCols:6})).ndjson)
const relief=workbook.worksheets.getItem('Relief')
assert.equal(relief.getRange('D10').values[0][0],17)
relief.getRange('B14').values=[[2]]
workbook.recalculate()
assert.equal(relief.getRange('D10').values[0][0],39)
relief.getRange('B14').values=[[1]]
workbook.recalculate()
assert.equal(relief.getRange('D10').values[0][0],17)
for(const [sheet,range] of [['Summary','A1:C15'],['Population','A1:C23'],['Shelters','A1:E10'],['Relief','A1:F10'],['Relief','A13:L23']]) {
  const preview=await workbook.render({sheetName:sheet,range,scale:1.4,format:'png'})
  await fs.writeFile(path.join(out,`${sheet}-${range.replace(':','-')}.png`),new Uint8Array(await preview.arrayBuffer()))
}
console.log('Workbook formula and visual QA complete')
